  it('a restart clears an auto-archive marker before the resume, so the resumed turn never archives (CAN-6014)', async () => {
    const { target, repository } = serviceWithRepository();
    Object.defineProperty(target, 'reconcileHostRuntime', { value: true });
    await createChat(target);
    await target.command(
      envelope('mark-auto-archive', {
        type: 'chat.patch_tab_settings',
        tabId: 'chat-1',
        patch: { autoArchive: true },
      }),
    );
    await observeTurn(
      target,
      turnStarted(
        { ...SCOPE, chatId: 'chat-1' },
        { sequence: 9_001, turnId: 'turn-interrupted', atMs: 10 },
      ),
    );
    await repository.transact(
      SCOPE,
      [
        {
          type: 'runtime.patched',
          chatId: 'chat-1',
          runtime: {
            ...(await repository.getState(SCOPE)).runtimeByChatId['chat-1'],
            status: 'streaming',
            queuedMessageIds: [],
          },
        },
      ],
      { source: 'provider', mutationId: 'interrupted-turn' },
    );
    const dispatched: string[] = [];
    const archiver = new ChatAutoArchiver({
      onTurnStateCommitted: (listener) => target.onTurnStateCommitted(listener),
      onUnblocked: () => (): void => undefined,
      readSnapshot: (scope) => target.getCommittedWatcherSnapshot(scope),
      closeBlocked: () => false,
      locked: () => false,
      dispatchInFlight: () => false,
      dispatch: (request) => {
        dispatched.push(request.command.type);
        return target.command(request);
      },
      warn: () => undefined,
    });
    archiver.start();
    try {
      const reconciled = await target.getState(SCOPE);
      expect(reconciled.tabsFile.tabs[0]?.autoArchive).toBeUndefined();
      await observeTurn(
        target,
        turnStarted(
          { ...SCOPE, chatId: 'chat-1' },
          {
            sequence: 9_002,
            turnId: 'turn-resumed',
            atMs: 20,
            origin: 'restart',
          },
        ),
      );
      await observeTurn(
        target,
        turnEnded(
          { ...SCOPE, chatId: 'chat-1' },
          {
            sequence: 9_003,
            turnId: 'turn-resumed',
            atMs: 30,
            origin: 'restart',
          },
        ),
      );
      await archiver.settled();
      const after = await target.getState(SCOPE);
      expect(after.archives).toEqual([]);
      expect(after.tabsFile.tabs.map((tab) => tab.id)).toEqual(['chat-1']);
      expect(dispatched).not.toContain('chat.archive_tab');
    } finally {
      archiver.stop();
    }
  });

  it.each([
    'streaming',
    'idle',
    'interrupted',
    'registry-failure',
    'live-terminal',
  ] as const)(
    'registers and settles an orphaned %s turn before resume',
    async (status) => {
      const { target, repository } = serviceWithRepository();
      Object.defineProperty(target, 'reconcileHostRuntime', { value: true });
      await createChat(target);
      const created = await target.getState(SCOPE);
      const createdTab = created.tabsFile.tabs[0];
      if (!createdTab) throw new Error('Expected created chat tab');

      await repository.transact(
        SCOPE,
        [
          {
            type: 'tab.created',
            tab: {
              ...createdTab,
              messages: [
                {
                  id: 'user-orphaned',
                  role: 'user',
                  timestamp: 10,
                  blocks: [{ type: 'text', text: 'Finish this turn' }],
                },
                {
                  id: 'timer-orphaned',
                  role: 'system',
                  timestamp: 10,
                  blocks: [
                    { type: 'turn_timer', startedAt: 10, completedAt: null },
                  ],
                },
              ],
            },
          },
          {
            type: 'runtime.patched',
            chatId: 'chat-1',
            runtime: {
              status:
                status === 'registry-failure' || status === 'live-terminal'
                  ? 'streaming'
                  : status,
              queuedMessageIds: [],
              activeTurn: { userMessageId: 'user-orphaned', startedAt: 10 },
            },
          },
          {
            type: 'pending_question.upserted',
            question: {
              requestId: 'sync-question',
              chatId: 'chat-1',
              questions: [{ question: 'Still running?', options: ['Yes'] }],
            },
          },
          {
            type: 'pending_question.upserted',
            question: {
              requestId: 'async-question',
              chatId: 'chat-1',
              delivery: 'async',
              questions: [{ question: 'Which scope?', options: ['Focused'] }],
            },
          },
        ],
        { source: 'provider', mutationId: 'orphaned-turn' },
      );

      if (status === 'live-terminal') {
        mockTerminalState.mockReturnValue({ turnState: 'running' });
        const snapshot = await target.getState(SCOPE);
        expect(snapshot.runtimeByChatId['chat-1'].status).toBe('streaming');
        expect(mockRecordInterruptedChats).not.toHaveBeenCalled();
        mockTerminalState.mockReturnValue(undefined);
      }
      if (status === 'registry-failure') {
        mockRecordInterruptedChats.mockRejectedValueOnce(
          new Error('registry unavailable'),
        );
        await expect(target.getState(SCOPE)).rejects.toThrow(
          'registry unavailable',
        );
        expect(
          (await repository.getState(SCOPE)).runtimeByChatId['chat-1'].status,
        ).toBe('streaming');
      }
      const reconciled = await target.getState(SCOPE);
      expect(mockRecordInterruptedChats).toHaveBeenCalledWith([
        expect.objectContaining({
          ...SCOPE,
          chatId: 'chat-1',
          resumeReason: 'app_shutdown',
        }),
      ]);
      expect(reconciled.runtimeByChatId['chat-1']).toMatchObject({
        status: 'interrupted',
        error: { code: 'interrupted', retryable: true },
      });
      expect(reconciled.runtimeByChatId['chat-1']).not.toHaveProperty(
        'activeTurn',
      );
      expect(reconciled.tabsFile.tabs[0]?.messages[1]).toMatchObject({
        id: 'timer-orphaned',
        blocks: [
          {
            type: 'turn_timer',
            startedAt: 10,
            completedAt: 10,
          },
        ],
      });
      expect(reconciled.tabsFile.pendingQuestions).toEqual([
        expect.objectContaining({
          requestId: 'async-question',
          delivery: 'async',
        }),
      ]);
      mockRecordInterruptedChats.mockClear();
      await target.getState(SCOPE);
      expect(mockRecordInterruptedChats).not.toHaveBeenCalled();
    },
  );

